if ($a[0] == 0) {
    echo "YES\n";
    exit(0);
}

$n = $a[1]; // a[1] is the limit for loops

for ($ta = 0; $ta < $n; $ta++) {
    $tmp = $a[2] - ($ta * $a[4]);
    if ($tmp == $a[0]) {
        echo "YES\n";
        exit(0);
    }
}

for ($tb = 0; $tb < $n; $tb++) {
    $tmp = $a[3] - ($tb * $a[5]);
    if ($tmp == $a[0]) {
        echo "YES\n";
        exit(0);
    }
}

for ($ta = 0; $ta < $n; $ta++) {
    for ($tb = 0; $tb < $n; $tb++) {
        $tmp = ($a[2] - $ta * $a[4]) + ($a[3] - $tb * $a[5]);
        if ($tmp == $a[0]) {
            echo "YES\n";
            exit(0);
        }
    }
}

echo "NO\n";
exit(0);
?>

